'use strict';
Object.assign(TRANSLATIONS.en,{'发运月份':'Shipment Month','计划发运数量（吨）':'Planned Shipment Quantity (MT)','已发运出库数量（吨）':'Dispatched Quantity (MT)','计划发运数量':'Planned Shipment Quantity','已发运出库数量':'Dispatched Quantity','本页为系统审计日志，记录账户、安全、权限及业务操作。单据作业记录请在对应业务详情中查看。':'System audit records include account, security, permission and business events. Document operation records are available in the corresponding document details.','单据作业记录':'Document Operation Records','系统审计日志':'System Audit Log','版权声明':'Copyright Notice','软件著作权人：唐雷。保留所有权利。':'Copyright © 2026 Tang Lei. All rights reserved.'});
I18n.pattern=new RegExp(Object.keys(TRANSLATIONS.en).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
const v35Translate=I18n.translate.bind(I18n);I18n.translate=function(text,ui){if(typeof text==='string'&&!this.protected.has(text.trim()))text=text.replace(/备货月份/g,'发运月份').replace(/出库单号/g,'装箱单号').replace(/作业记录（最近500条，历史不覆盖）/g,'单据作业记录');return v35Translate(text,ui);};
const v35Init=Router.init.bind(Router);Router.init=async function(){this.add(/^\/sales-plans\/([0-9a-f-]{36})$/,id=>Shipping.plan(id));return v35Init();};
const v35Plan=Shipping.plan.bind(Shipping);Shipping.plan=async function(id){await v35Plan(id);const a=document.createElement('a');a.href='/sales-plans';a.className='button secondary';a.textContent='返回销售管理';$('page-content').prepend(a);I18n.apply();};
// Redirect old bookmarks to the sales namespace so menu selection is consistent.
const v35Show=Router.performShow.bind(Router);Router.performShow=async function(){const m=location.pathname.match(/^\/preparation\/plans\/([0-9a-f-]{36})\/shipping$/);if(m)history.replaceState({},'','/sales-plans/'+m[1]+location.search);return v35Show();};
const v35Audit=V27Reliability.audit.bind(V27Reliability);V27Reliability.audit=async function(){await v35Audit();$('business-title').textContent=I18n.translate('系统审计日志');const note=document.createElement('p');note.className='v35-audit-intro';note.textContent=I18n.translate('本页为系统审计日志，记录账户、安全、权限及业务操作。单据作业记录请在对应业务详情中查看。');$('page-content').prepend(note);I18n.apply();};
const v35AuditAction=V27Reliability.auditAction.bind(V27Reliability);V27Reliability.auditAction=code=>I18n.translate(AuditLabels.label(code)||v35AuditAction(code));
const v35History=Business.bundleHistory.bind(Business);Business.bundleHistory=async function(id){await v35History(id);for(const code of $('page-content').querySelectorAll('[data-audit-action]'))code.textContent=I18n.translate(AuditLabels.label(code.dataset.auditAction));I18n.apply();};
EmployeeIdentity.refresh();
